
using System;
using System.IO;
using System.Diagnostics;
using System.Net;
using System.Text;

namespace EQNProAgentInstaller
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.Title = "EQN Pro Agent v2.1.0 - Diagnostic Bootstrap";
            Console.WriteLine("====================================================");
            Console.WriteLine("    EQN PRO AGENT INSTALLER & DIAGNOSTIC        ");
            Console.WriteLine("====================================================");
            Console.WriteLine();

            string installDir = @"C:\ProgramData\EQNProAgent";
            string serverUrl = "https://eqn-pro-dashboard.vercel.app/api/agent";

            try
            {
                // 1. Connectivity Check
                Console.Write("[1/4] Checking Dashboard Connectivity... ");
                using (var client = new WebClient())
                {
                    // Simple HEAD request or GET to ensure reachability
                    client.DownloadString("https://eqn-pro-dashboard.vercel.app/api/stats");
                    Console.ForegroundColor = ConsoleColor.Green;
                    Console.WriteLine("SUCCESS");
                    Console.ResetColor();
                }

                // 2. Directory Setup
                Console.Write("[2/4] Initializing Environment... ");
                if (!Directory.Exists(installDir)) Directory.CreateDirectory(installDir);
                Console.ForegroundColor = ConsoleColor.Green;
                Console.WriteLine("DONE");
                Console.ResetColor();

                // 3. Extraction
                Console.Write("[3/4] Extracting Agent Engine... ");
                string agentPath = Path.Combine(installDir, "agent.ps1");
                string base64Script = "";
                byte[] scriptBytes = Convert.FromBase64String(base64Script);
                File.WriteAllBytes(agentPath, scriptBytes);
                Console.ForegroundColor = ConsoleColor.Green;
                Console.WriteLine("DONE");
                Console.ResetColor();

                // 4. Persistence & Launch
                Console.Write("[4/4] Registering System Persistence... ");
                string setupScriptPath = Path.Combine(installDir, "setup.ps1");
                string setupScript = @"
                    $agentPath = 'C:\ProgramData\EQNProAgent\agent.ps1'
                    $taskName = 'EQNProAgent'
                    $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument ""-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File `""$agentPath`""""
                    $trigger = New-ScheduledTaskTrigger -AtStartup
                    $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable
                    $principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -RunLevel Highest
                    
                    if (Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue) {
                        Unregister-ScheduledTask -TaskName $taskName -Confirm:$false
                    }
                    Register-ScheduledTask -TaskName $taskName -Action $action -Trigger $trigger -Principal $principal -Settings $settings -Force
                    Start-ScheduledTask -TaskName $taskName
                ";
                File.WriteAllText(setupScriptPath, setupScript);

                ProcessStartInfo psi = new ProcessStartInfo
                {
                    FileName = "powershell.exe",
                    Arguments = string.Format("-NoProfile -ExecutionPolicy Bypass -File \"{0}\"", setupScriptPath),
                    UseShellExecute = false,
                    CreateNoWindow = true
                };
                
                Process p = Process.Start(psi);
                p.WaitForExit();
                
                if (File.Exists(setupScriptPath)) File.Delete(setupScriptPath);
                Console.ForegroundColor = ConsoleColor.Green;
                Console.WriteLine("SUCCESS");
                Console.ResetColor();

                Console.WriteLine();
                Console.ForegroundColor = ConsoleColor.Cyan;
                Console.WriteLine("Installation Complete.");
                Console.WriteLine("The agent is now running as a SYSTEM task.");
                Console.WriteLine("Check your dashboard: https://eqn-pro-dashboard.vercel.app");
                Console.ResetColor();
                Console.WriteLine("\n[Press any key to exit]");
                Console.ReadKey();
            }
            catch (Exception ex)
            {
                Console.ForegroundColor = ConsoleColor.Red;
                Console.WriteLine("\nFAILED");
                Console.WriteLine("----------------------------------------------------");
                Console.WriteLine("ERROR: " + ex.Message);
                Console.WriteLine("----------------------------------------------------");
                Console.ResetColor();
                
                string errorLog = Path.Combine(installDir, "install_error.log");
                File.WriteAllText(errorLog, ex.ToString());
                Console.WriteLine("\nDetails logged to: " + errorLog);
                Console.WriteLine("\n[Press any key to exit]");
                Console.ReadKey();
            }
        }
    }
}
